<https://example.org/openevidence/questions/q_nephrotic_syndrome_treatment> a holon:ClinicalQuestionHolon ;
    oe:questionText "What is the recommended first-line pharmacological treatment for Nephrotic Syndrome?"^^xsd:string ;
    oe:answerText "B-cell depletion with rituximab induces sustained remission in children with steroid-dependent or frequently relapsing nephrotic syndrome. However, most patients relapse after B-cell recovery, and some patients do not achieve B-cell depletion."^^xsd:string ;
    oe:belongsToSpecialty "Nephrology" ;
    holon:hasInteriorGraph <https://example.org/openevidence/questions/q_nephrotic_syndrome_treatment-int> ;
    holon:hasBoundaryGraph <https://example.org/openevidence/questions/q_nephrotic_syndrome_treatment-bou> ;
    holon:hasProjectionGraph <https://example.org/openevidence/questions/q_nephrotic_syndrome_treatment-pro> ;
    holon:hasContextGraph <https://example.org/openevidence/questions/q_nephrotic_syndrome_treatment-con> ;
    holon:evidenceQualityThreshold "0.50"^^xsd:decimal .

<https://example.org/openevidence/drugs/prednisone> oe:treats <https://example.org/openevidence/diseases/nephrotic_syndrome> .
